// Service worker: offline-first app shell (dev/DESIGN.md §0, §1; plan §8-1).
//
// - Every URL here is relative to this file, so the app works under a GitHub Pages sub-path; scope is ./
// - The precache list and CACHE_VERSION between the markers below are generated by
//   dev/build_sw_list.ps1. Run it before every deploy; it bumps CACHE_VERSION when any file changed.
// - Install fills a new versioned cache and then WAITS. The page shows "새 버전이 있습니다 [지금 적용]"
//   and posts { type: 'SKIP_WAITING' } (see js/io/swclient.js). Activation deletes old caches.
// - Fetch: only same-origin GET requests inside the scope are handled; everything else goes straight to
//   the network untouched. Precached files are served cache-first. Page navigations fall back to the
//   cached index.html when offline.
// - On localhost / 127.0.0.1 (development) the order is network-first, so edited files show up at once;
//   the cache is still used when the dev server is unreachable.
// - Project data never goes through here: it lives in IndexedDB (js/io/storage.js).

// PRECACHE-START (generated by dev/build_sw_list.ps1 - do not edit by hand)
const CACHE_VERSION = 'b40-4d50cc72';
const PRECACHE = [
  './',
  './css/app.css',
  './css/checks.css',
  './css/fixtures.css',
  './css/openings.css',
  './css/output.css',
  './css/settings.css',
  './devtest/devtest.css',
  './devtest/devtest.js',
  './devtest/index.html',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon-maskable-512.png',
  './icons/icon.svg',
  './index.html',
  './js/core/checkkeys.js',
  './js/core/checks-full.js',
  './js/core/checks.js',
  './js/core/dims.js',
  './js/core/erase.js',
  './js/core/fixtures.js',
  './js/core/geom.js',
  './js/core/graph.js',
  './js/core/labels.js',
  './js/core/memo.js',
  './js/core/model.js',
  './js/core/openings.js',
  './js/core/prefs.js',
  './js/core/printlayout.js',
  './js/core/rooms.js',
  './js/core/rotate.js',
  './js/core/sketch.js',
  './js/core/solver.js',
  './js/io/export.js',
  './js/io/fileio.js',
  './js/io/storage.js',
  './js/io/swclient.js',
  './js/main.js',
  './js/ui/checks-ui.js',
  './js/ui/draw-dims.js',
  './js/ui/draw-fixtures.js',
  './js/ui/draw-labels.js',
  './js/ui/draw-openings.js',
  './js/ui/eraser-ui.js',
  './js/ui/fixtures-ui.js',
  './js/ui/info-form.js',
  './js/ui/input.js',
  './js/ui/list.js',
  './js/ui/memo-ui.js',
  './js/ui/openings-ui.js',
  './js/ui/output.js',
  './js/ui/panel.js',
  './js/ui/render.js',
  './js/ui/settings.js',
  './js/ui/theme.js',
  './js/ui/tools.js',
  './js/ui/view.js',
  './js/ui/wiring.js',
  './js/version.js',
  './manifest.webmanifest',
];
// PRECACHE-END

const CACHE_PREFIX = 'floorplan-';
const CACHE_NAME = CACHE_PREFIX + CACHE_VERSION;
const SCOPE = self.registration.scope; // absolute URL ending in '/'
const INDEX_URL = new URL('./index.html', SCOPE).href;
const DEV_HOSTS = ['localhost', '127.0.0.1', '[::1]'];
const IS_DEV = DEV_HOSTS.includes(self.location.hostname);
// Paths (relative to the scope) that are never cached at runtime: unit tests change all the time.
const NO_RUNTIME_CACHE = ['tests/'];

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    // cache: 'reload' bypasses the HTTP cache (GitHub Pages sends max-age=600), so a new version never
    // gets stored with stale files. addAll is atomic: if one file fails, the install fails and the old
    // version stays in use.
    await cache.addAll(PRECACHE.map((url) => new Request(new URL(url, SCOPE).href, { cache: 'reload' })));
    // No skipWaiting() here: the new version waits until the page asks for it.
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names
      .filter((name) => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME)
      .map((name) => caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  const data = event.data || {};
  if (data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  } else if (data.type === 'GET_VERSION') {
    const reply = { type: 'VERSION', version: CACHE_VERSION };
    if (event.ports && event.ports[0]) event.ports[0].postMessage(reply);
    else if (event.source) event.source.postMessage(reply);
  }
});

function isHandled(request) {
  if (request.method !== 'GET') return false;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return false;
  if (!url.href.startsWith(SCOPE)) return false;
  // Range requests (media seeking) are not worth caching.
  if (request.headers.has('range')) return false;
  return true;
}

function mayCacheAtRuntime(request, response) {
  if (!response || response.status !== 200 || response.type !== 'basic') return false;
  // URLs with a query string are not app files (and would fill the cache with variants).
  if (new URL(request.url).search) return false;
  const path = request.url.slice(SCOPE.length);
  return !NO_RUNTIME_CACHE.some((prefix) => path.startsWith(prefix));
}

async function fromCache(request) {
  const cache = await caches.open(CACHE_NAME);
  const isNavigation = request.mode === 'navigate';
  // ignoreVary: GitHub Pages sends "Vary: Accept-Encoding"; the stored copy is fine for any request.
  let hit = await cache.match(request, { ignoreSearch: isNavigation, ignoreVary: true });
  if (!hit && isNavigation) {
    // './' and './index.html' are the same page.
    const url = new URL(request.url);
    if (url.pathname.endsWith('/')) {
      hit = await cache.match(new URL('index.html', url).href, { ignoreSearch: true, ignoreVary: true });
    }
  }
  return hit || null;
}

async function fromNetwork(request) {
  const response = await fetch(request);
  if (mayCacheAtRuntime(request, response)) {
    // A file missing from the precache list (build script not run) still works offline after one use.
    const copy = response.clone();
    caches.open(CACHE_NAME).then((cache) => cache.put(request, copy)).catch(() => {});
  }
  return response;
}

async function offlineFallback(request) {
  if (request.mode === 'navigate') {
    const cache = await caches.open(CACHE_NAME);
    const index = await cache.match(INDEX_URL);
    if (index) return index;
  }
  return new Response('인터넷에 연결되어 있지 않고, 이 파일은 기기에 저장되어 있지 않습니다.', {
    status: 503,
    headers: { 'Content-Type': 'text/plain; charset=utf-8' },
  });
}

async function cacheFirst(request) {
  const hit = await fromCache(request);
  if (hit) return hit;
  try {
    return await fromNetwork(request);
  } catch (_) {
    return offlineFallback(request);
  }
}

async function networkFirst(request) {
  try {
    return await fromNetwork(request);
  } catch (_) {
    const hit = await fromCache(request);
    return hit || offlineFallback(request);
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (!isHandled(request)) return; // let the browser handle it normally
  event.respondWith(IS_DEV ? networkFirst(request) : cacheFirst(request));
});
